  var parts=f.formatToParts(dt); var o={}; parts.forEach(function(p){ o[p.type]=p.value; }); return o; }
function convert(epochMs, fromTz, toTz){ return {from: tzParts(epochMs, fromTz), to: tzParts(epochMs, toTz)}; }
